  final String? deletedAt;
  final String title;
  final String? lifeAreaId;

  /// A day as `YYYY-MM-DD`.
  final String? targetDate;

  /// One sign that tells the user the goal is reached.
  final String? doneWhen;

  /// 0 to 100, set by the user.
  final int progress;
  const Goal({
    required this.id,
